ruleToc.chapterList:
@js:
(function(){
  try{ book.type = 32; }catch(e){}
  var base = 'https://search.kuwo.cn/r.s?stype=albuminfo&loginUid=0&loginSid=null&prod=kwplayer_ar_9.1.7.0&bkprod=kwbook_ar_9.1.7.0&source=kwplayer_ar_9.1.7.0_t18.apk&bksource=kwbook_ar_9.1.7.0_t18.apk&corp=kuwo&albumid=';
  var tail = '&pn=';
  var tail2 = '&rn=100&show_copyright_off=1&vipver=MUSIC_8.2.0.0_BCS17&mobi=1&sortby=3&iskwbook=1';
  var bid = '';
  try{ var tm = String(book.tocUrl || '').match(/albumid=(\d+)/); if(tm) bid = tm[1]; }catch(e){}
  if(!bid){ var tm2 = String(result || '').match(/albumid=(\d+)/); if(tm2) bid = tm2[1]; }
  // 第一次请求用传入的 result (当前页)
  var out = [];
  var seen = {};
  var songnum = 0;
  var first = null;
  try{ first = JSON.parse(result); }catch(e){}
  var pages = [];
  if(first && first.musiclist){ pages.push(first); }
  songnum = Number((first && first.songnum) || 0);
  // 循环拉剩余页 (最多20页=2000集)
  var maxPg = songnum ? Math.ceil(songnum/100) : 1;
  if(maxPg > 20) maxPg = 20;
  for (var p=1; p<maxPg; p++){
    try{
      var u = base + bid + tail + p + tail2;
      var txt = java.ajax(u);
      var j = JSON.parse(txt);
      if(j && j.musiclist && j.musiclist.length) pages.push(j);
      else break;
    }catch(e){ break; }
  }
  for (var i=0;i<pages.length;i++){
    var ml = pages[i].musiclist || [];
    for (var j=0;j<ml.length;j++){
      var it = ml[j] || {};
      var id = String(it.id || it.musicrid || '');
      if (!id || seen[id]) continue;
      seen[id] = 1;
      var nm = it.name || '';
      // 过滤广告集/简介集: 极速30s/极速听/30秒/预告/宣传等
      if (/极速\s*\d*\s*s|极速听|\d+\s*秒|预告|宣传|推广|花絮|简介/i.test(nm)) continue;
      // 集数纯数字: 第001集xxx -> 1 ; 001-xxx -> 1
      var t = nm.replace(/^\s*第\s*0*(\d+)\s*集.*$/, '$1');
      if (t === nm) t = nm.replace(/^\s*0*(\d+)\s*[-_:\s]/, '$1');
      t = t.replace(/[#$]/g, '').trim();
      if (!t) t = String(out.length + 1);
      out.push({
        name: t,
        url: 'https://mobi.kuwo.cn/mobi.s?f=web&user=0&source=kwplayercar_ar_6.0.0.9_B_jiakong_vh.apk&type=convert_url_with_sign&rid=' + id + '&br=128kmp3'
      });
    }
  }
  return out;
})()
